)v(discipline,topic,position,content)
join public.disciplines d on d.name=v.discipline
join public.topics t on t.discipline_id=d.id and t.name=v.topic
join public.materials m on m.topic_id=t.id
where ms.material_id=m.id and ms.position=v.position;

insert into public.material_citations(material_id,source_id,citation_label)
select m.id,s.id,x.label
from (values
 ('Ensino de Matemática nos Anos Iniciais','Base Nacional Comum Curricular — Educação Infantil e Ensino Fundamental','BNCC — Matemática'),
 ('Ensino de Matemática nos Anos Iniciais','Fundamentos e Práticas no Ensino de Matemática - Unidades temáticas - Matemática nos anos iniciais','UNIVESP — Ensino de Matemática')
) x(discipline,source_title,label)
join public.disciplines d on d.name=x.discipline
join public.topics t on t.discipline_id=d.id
join public.materials m on m.topic_id=t.id
join public.sources s on s.title=x.source_title
where not exists(select 1 from public.material_citations mc where mc.material_id=m.id and mc.source_id=s.id);